mapper.update:
UPDATE kb_documents
SET status = 'failed',
    chunk_count = 0,
    lease_until = NULL,
    next_attempt_at = NULL,
    error_code = #{errorCode},
    error_message = #{errorMessage}
WHERE id = #{id}
  AND user_id = #{userId}
  AND version = #{version}
  AND status = 'processing'
